<script>function editProduct(product){const dialog=document.getElementById('edit-dialog');document.getElementById('edit-form').action='/inventory/'+product.id;['name','category','cost_price','retail_price','stock'].forEach(field=>document.getElementById('edit-'+field).value=product[field]);dialog.showModal()}function filterRows(value){const query=value.toLowerCase();document.querySelectorAll('.product-row').forEach(row=>row.hidden=!row.dataset.search.includes(query))}</script>
